import orders from './orders.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Return the current status of an order. Include chronological history only when requested.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string' },
          include_history: { type: 'boolean' }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  if (typeof args.order_id !== 'string') {
    throw new Error('order_id must be a string');
  }
  const includeHistory = args.include_history === undefined ? false : args.include_history;
  if (typeof includeHistory !== 'boolean') {
    throw new Error('include_history must be a boolean');
  }

  const order = orders[args.order_id];
  if (!order) {
    throw new Error(`Order not found: ${args.order_id}`);
  }

  let text = order.status;
  if (includeHistory) {
    text = order.history.join('\n');
  }

  return {
    content: [{ type: 'text', text }]
  };
}

